"use client";

import AppShell from "@/components/Navbar";
import { useEffect, useMemo, useState } from "react";
import { api } from "@/lib/api";
import Link from "next/link";

interface RoomType {
  id: number;
  name: string;
}

interface Room {
  id: number;
  room_number: string;
  building: string;
  capacity: number;
  is_available: boolean;
  type?: RoomType | null;
}

interface RoomsResponse {
  success: boolean;
  message: string;
  data: Room[];
  meta: { total: number; page: number; per_page: number };
}

interface RoomTypesResponse {
  success: boolean;
  message: string;
  data: RoomType[];
}

export default function AdminRoomsPage() {
  const [rows, setRows] = useState<Room[]>([]);
  const [types, setTypes] = useState<RoomType[]>([]);
  const [meta, setMeta] = useState({ total: 0, page: 1, per_page: 15 });
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(true);
  const [togglingId, setTogglingId] = useState<number | null>(null);
  const [error, setError] = useState<string | null>(null);

  const [search, setSearch] = useState("");
  const [typeFilter, setTypeFilter] = useState<string>("all");
  const [availFilter, setAvailFilter] = useState<string>("all");

  async function loadRooms() {
    try {
      setLoading(true);
      setError(null);
      const res = await api.get<RoomsResponse>(`/admin/rooms?page=${page}`);
      setRows(res.data ?? []);
      setMeta(res.meta ?? { total: 0, page, per_page: 15 });
    } catch (e) {
      setError(e instanceof Error ? e.message : "Failed to load rooms.");
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    loadRooms();
  }, [page]);

  useEffect(() => {
    (async () => {
      try {
        const res = await api.get<RoomTypesResponse>("/admin/room-types");
        setTypes(res.data ?? []);
      } catch {
        setTypes([]);
      }
    })();
  }, []);

  async function toggleAvailability(id: number) {
    try {
      setTogglingId(id);
      setError(null);
      await api.patch(`/admin/rooms/${id}/toggle`, {});
      await loadRooms();
    } catch (e) {
      setError(e instanceof Error ? e.message : "Failed to toggle availability.");
    } finally {
      setTogglingId(null);
    }
  }

  const filtered = useMemo(() => {
    return rows.filter((r) => {
      const matchSearch =
        r.room_number.toLowerCase().includes(search.toLowerCase()) ||
        r.building.toLowerCase().includes(search.toLowerCase());
      const matchType = typeFilter === "all" || r.type?.name === typeFilter;
      const matchAvail =
        availFilter === "all" ||
        (availFilter === "available" && r.is_available) ||
        (availFilter === "unavailable" && !r.is_available);
      return matchSearch && matchType && matchAvail;
    });
  }, [rows, search, typeFilter, availFilter]);

  const totalPages = Math.max(1, Math.ceil(meta.total / meta.per_page));
  const stats = {
    total: meta.total,
    available: rows.filter((r) => r.is_available).length,
    unavailable: rows.filter((r) => !r.is_available).length,
  };

  return (
    <AppShell role="admin" userName="Admin" pageTitle="Room Management">
      <div className="animate-fade-in space-y-4">
        <div className="flex items-start justify-between gap-3 flex-wrap">
          <div>
            <h1 className="text-[20px] font-bold" style={{ color: "var(--color-text)" }}>Room Management</h1>
            <p className="text-sm mt-0.5" style={{ color: "var(--color-text-muted)" }}>
              Manage campus rooms, availability, and capacity settings.
            </p>
          </div>
          <Link href="/admin/rooms/create" className="btn btn-primary btn-sm">
            Create Room
          </Link>
        </div>

        {error && (
          <div className="rounded-lg border px-3 py-2 text-[12px]" style={{ borderColor: "#fecaca", background: "#fff1f2", color: "#9f1239" }}>
            {error}
          </div>
        )}

        <div className="grid grid-cols-3 gap-4">
          <StatCard label="Total Rooms" value={stats.total} />
          <StatCard label="Available" value={stats.available} />
          <StatCard label="Unavailable" value={stats.unavailable} />
        </div>

        <div className="card">
          <div className="card-body flex flex-wrap items-center gap-3">
            <input
              type="search"
              placeholder="Search by room number or building..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="flex-1 min-w-[220px]"
            />
            <select value={typeFilter} onChange={(e) => setTypeFilter(e.target.value)}>
              <option value="all">All Types</option>
              {types.map((t) => <option key={t.id} value={t.name}>{t.name}</option>)}
            </select>
            <select value={availFilter} onChange={(e) => setAvailFilter(e.target.value)}>
              <option value="all">All Status</option>
              <option value="available">Available</option>
              <option value="unavailable">Unavailable</option>
            </select>
            <span className="text-xs ml-auto" style={{ color: "var(--color-text-muted)" }}>{filtered.length} of {rows.length} loaded</span>
          </div>
        </div>

        <div className="card overflow-x-auto">
          <table className="table-base">
            <thead>
              <tr>
                <th>Room</th><th>Building</th><th>Type</th><th>Capacity</th><th>Status</th><th className="text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {loading ? (
                <tr><td colSpan={6} className="text-center py-10">Loading...</td></tr>
              ) : filtered.length === 0 ? (
                <tr><td colSpan={6} className="text-center py-10">No rooms match your filters.</td></tr>
              ) : (
                filtered.map((room) => (
                  <tr key={room.id}>
                    <td className="font-semibold">{room.room_number}</td>
                    <td>{room.building}</td>
                    <td>{room.type?.name ?? "N/A"}</td>
                    <td>{room.capacity}</td>
                    <td>{room.is_available ? "Available" : "Unavailable"}</td>
                    <td>
                      <div className="flex justify-end gap-2">
                        <Link href={`/admin/rooms/${room.id}`} className="btn btn-ghost btn-sm">Edit</Link>
                        <button
                          className="btn btn-sm btn-outline"
                          onClick={() => toggleAvailability(room.id)}
                          disabled={togglingId === room.id}
                        >
                          {togglingId === room.id ? "..." : room.is_available ? "Disable" : "Enable"}
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>

        <div className="flex items-center justify-between">
          <p className="text-xs" style={{ color: "var(--color-text-muted)" }}>Page {meta.page} of {totalPages}</p>
          <div className="flex gap-2">
            <button className="btn btn-outline btn-sm" disabled={page <= 1} onClick={() => setPage((p) => Math.max(1, p - 1))}>Previous</button>
            <button className="btn btn-outline btn-sm" disabled={page >= totalPages} onClick={() => setPage((p) => Math.min(totalPages, p + 1))}>Next</button>
          </div>
        </div>
      </div>
    </AppShell>
  );
}

function StatCard({ label, value }: { label: string; value: number }) {
  return (
    <div className="card card-body flex items-center justify-between">
      <span className="text-sm" style={{ color: "var(--color-text-secondary)" }}>{label}</span>
      <span className="text-base font-semibold">{value}</span>
    </div>
  );
}
